import subprocess,os,json
from pathlib import Path
root=Path('/nexus/Dev/OpenCog/NL2PLN_Project/PeTTaChainer');base=Path('/tmp/stationops-reuse')
for seed,budget in [(7,600),(11,300),(23,300)]:
 for r in ([-1,0,.5,1] if seed!=11 else [1,.5,0,-1]):
  label='control' if r<0 else str(r)
  name=f'seed{seed}-r{label}'
  with (base/(name+'.log')).open('w') as log:
   try:
    p=subprocess.run([str(root/'.venv/bin/python'),str(base/'benchmark.py'),'--repository',str(base/'runtime'),'--chainergame',str(root/'../../ChainerGame'),'--petta',str(root/'third_party/petta'),'--json-out',str(base/(name+'.json')),'--seed',str(seed),'--budget',str(budget),'--refinement',str(r)],stdout=log,stderr=subprocess.STDOUT,timeout=240,env={**os.environ,'PYTHONDONTWRITEBYTECODE':'1'})
    print(name,p.returncode,flush=True)
   except subprocess.TimeoutExpired: print(name,'TIMEOUT',flush=True)

