import json,glob,re
from pathlib import Path
base=Path('/tmp/stationops-reuse')
def norm(x):
 if isinstance(x,str):return re.sub(r'kb[0-9a-fA-F-]{20,}', 'kbUUID',x)
 if isinstance(x,list):return [norm(y) for y in x]
 if isinstance(x,dict):return {k:norm(v) for k,v in x.items()}
 return x
rows=[]
for f in sorted(base.glob('seed*-r*.json')):
 d=json.loads(f.read_text());seed=d['workload']['seed'];r=d['workload']['refinement']
 for b,episode in zip(d['batches'],d['result']['rounds']):
  p={k:float(v) for k,v in b['probe'].items()}; assert b['metrics']['search_aborts']==0
  assert p['probe_reuse_claims']+p['probe_refine_claims']<=d['workload']['budget']+1
  if p['probe_first_steps_left']>=0:assert p['probe_refine_claims']<=int(p['probe_first_steps_left']*r)
  row=dict(run=f.stem,seed=seed,setting=r,shift=b['shift'],seconds=b['seconds'],coverage=episode['belief_metrics']['coverage'],brier=episode['belief_metrics']['brier_score'],beliefs=episode['beliefs'],probe=p,score=d['result']['aggregate']['station_score'],regret=d['result']['aggregate']['regret'])
  rows.append(row)
 if r==-1:
  old=Path('/tmp/stationops-refinement')/('new-600.json' if seed==7 else f'new-seed{seed}-b300-t0.json')
  prev=json.loads(old.read_text());assert norm([b['answers'] for b in d['batches']])==norm([b['answers'] for b in prev['batches']]),f
(base/'summary.json').write_text(json.dumps(rows,indent=2)+'\n')
for x in rows:print(x['run'],x['shift'],round(x['seconds'],2),x['coverage'],round(x['brier'],6),x['score'],x['regret'],x['probe'])
